static int failed = 0;

static void check(int i, char *got, const char *want) {
    if (!got || strcmp(got, want) != 0) {
        failed++;
        printf("case %d FAILED\n  got:  [%s]\n  want: [%s]\n", i, got ? got : "(null)", want);
    }
    free(got);
}

int main(void) {
    check(0, bill("rate 150\nbase 1200", "2024-06-03 08:15 4000\n2024-06-17 19:40 1500"), "base 1200\nflat 5500 units 825\nsum 2025");
