#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ratebill.h"

static int failed = 0;

static void check(int i, char *got, const char *want) {
    if (!got || strcmp(got, want) != 0) {
        failed++;
        printf("case %d FAILED
  got:  [%s]
  want: [%s]
", i, got ? got : "(null)", want);
    }
    free(got);
}

int main(void) {
    check(0, bill("rate 150
base 1200", "2024-06-03 08:15 4000
2024-06-17 19:40 1500"), "base 1200
day 5500 units 825
total 2025");
    check(1, bill("rate 150
window night 22:00-06:00 80
minimum 2500
base 600", "2024-06-03 23:30 400
2024-06-04 07:00 1000
2024-06-04 02:00 150"), "base 600
night 550 units 44
day 1000 units 150
minimum 1706
total 2500");
    check(2, bill("rate 200
allow 100 0
season 6,7 150
demand 3
round up", "2024-06-04 09:00 80
2024-06-03 09:00 70
2024-05-30 09:00 40"), "base 0
allow 100 units 0
day 90 units 27
demand 240
total 267");
    check(3, bill("rate 100
base 1000
tax 10
exempt base
credit 50
round down", "2024-06-04 09:00 1234"), "base 1000
day 1234 units 123
tax 12
credit -50
total 1085");
    if (failed) {
        printf("%d case(s) failed
", failed);
        return 1;
    }
    printf("all cases passed
");
    return 0;
}
